body=intro('Solutions / Agents & brokers','Be the agent they trust<br>before first contact.','Personal brand systems, listings-ready websites, content and video for values-driven real estate agents and brokers. Nationwide.','cire-homes.webp')
body+=section('The challenge','Buyers and sellers research you<br>before they ever call.',rows([('Looking like every other agent','A brokerage template doesn’t say who you are or who you serve best.'),('No home of your own online','Portal profiles and social links, but nowhere that is yours to send people.'),('No time to stay visible','Showings and closings leave little room for consistent posting and video.')]))
body+=section('Services for agents','Four ways we help<br>your name travel.',rows([('Personal Brand','An identity, voice and messaging that set you apart from the brokerage template. '+link('services/brand/','Brand Strategy & Identity')),('Listings-Ready Website','A custom site presenting listings, your story and areas, with lead-capture pages. '+link('services/websites/','Website & App Development')),('Content & Social','Social strategy, content calendars, email and local search. '+link('services/marketing/','Digital Marketing & Content')),('Video & Events','Professional video and photography, plus planning for open houses and client events. '+link('services/production/','Event & Video Production'))]),'solutions')
