body+=section('Upcoming events','The 2027 calendar.','<p class="body-copy">All dates are planned, not yet held. Details are shared with invited leaders.</p>'+rows([('February 2027','Founding invitations begin · Planned'),('June 2027','Inaugural Shepherd’s Roundtable · Planned'),('Date to be announced','Atlanta Leadership Dinner · Planned'),('Q3 2027','Inaugural Leadership Retreat · Planned')]),'upcoming')
