add('experiences','ABN Experiences',body)
body=intro('Resource Center','Thinking for leaders<br>and the work they build.','A podcast, practical guides and free tools are in preparation. Nothing here is published yet.','podcast.jpg')
body+=section('Coming soon / The Shepherd’s Diary','The conversations<br>behind the calling.','<p class="large-copy">A podcast exploring the experiences, perspectives and questions that shape the people who lead: ministry, culture, responsibility, relationships and personal growth.</p><p class="body-copy">No episodes are published yet. Listening links will appear here when the first episode is live.</p>'+contact_link('experience','Notify me at launch'),'diary')
body+=section('The library','Guides and insights,<br>in preparation.','<div class="resource-grid">'+''.join(f'<article id="{id}"><span class="tag">Coming soon</span><h3>{title}</h3><p>{text}</p></article>' for id,title,text in [('leadership-insights','Leadership & Ministry Insights','For pastors and ministry leaders navigating decisions few people see.'),('church-branding','Church Branding Resources','Identity, messaging and visual systems for congregations of every size.'),('digital-marketing','Digital Marketing Insights','Reaching people before Sunday, across the channels that matter.'),('real-estate-branding','Real Estate Branding Resources','Personal brand guidance for values-driven agents and brokers.')])+'</div>','library')
body+=section('Free downloads / Coming soon','Two tools,<br>in preparation.',rows([('The Church Brand Audit Checklist','25 things a church’s digital presence needs to turn first-time visitors into regular attenders.'),('The Faith-Based Agent Brand Toolkit','Five positioning moves that set values-driven agents apart, with the steps to apply each one.')])+'<p class="body-copy">Neither file is available yet.</p>'+contact_link('experience','Notify me when resources are ready'),'downloads')
add('resources','Resource Center',body)

