body+='''</div></fieldset><div class="field"><label for="message" id="message-label">What are you hoping to achieve?</label><textarea id="message" name="message" rows="5" required></textarea></div><div class="form-grid"><div class="field"><label for="timeline">Timeline</label><select id="timeline" name="timeline"><option>Exploring options</option><option>Ready to start now</option><option>In the next 3 months</option></select></div><div class="field"><label for="website">Website <span>(optional)</span></label><input id="website" name="website" type="url" placeholder="https://" autocomplete="url"></div></div><label class="consent"><input name="consent" type="checkbox" required><span>I understand this preview does not send or store my details.</span></label><button class="button" type="submit">Preview enquiry <span>↗</span></button><p class="form-note">Interactive preview. No details are sent or stored. Use the live company contact page to send an enquiry.</p></form><div class="form-success" id="form-success" hidden role="status" tabindex="-1"><span class="success-mark">✓</span><h2>Your brief<br>is taking shape.</h2><p>Your enquiry preview is complete. Nothing has been sent or stored.</p><button class="button" id="reset-form">Edit your enquiry <span>↗</span></button><a class="text-link" href="https://ascendbrandnetwork.com/work-with-us/" target="_blank" rel="noopener noreferrer">Continue to Ascend’s live contact page <span>↗</span></a></div></div></section>'''
